// 從前一節點取得參數
const params = $input.first().json;
const slackToken = params.slackToken;
const sourceChannel = params.sourceChannel;
const notifyChannel = params.notifyChannel;
const excludeNames = params.excludeNames;

// 計算目標日期（明確使用 Asia/Taipei 時區 UTC+8）
const now = new Date();
const taipeiOffset = 8 * 60; // UTC+8 in minutes
const localOffset = now.getTimezoneOffset(); // Server's local offset from UTC in minutes
const taipeiTime = new Date(now.getTime() + (taipeiOffset + localOffset) * 60 * 1000);

const dayOfWeek = taipeiTime.getDay();
const targetDates = [];

if (dayOfWeek === 1) {
  // 週一：檢查上週五、週六、週日、週一（4天）
  for (let i = 3; i >= 0; i--) {
    const date = new Date(taipeiTime);
    date.setDate(taipeiTime.getDate() - i);
    targetDates.push(date);
  }
} else if (dayOfWeek >= 2 && dayOfWeek <= 5) {
  // 週二到週五：只檢查前一天
  const date = new Date(taipeiTime);
  date.setDate(taipeiTime.getDate() - 1);
  targetDates.push(date);
} else {
  // 週末不執行（但以防萬一）
  return [{ json: { error: '不應在週末執行此工作流程', slackToken, notifyChannel } }];
}

// 格式化目標日期（YYYY-MM-DD）和標題格式（YYYYMMDD）
const targetDateStrs = [];
const targetDateTitles = [];

for (const date of targetDates) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  targetDateStrs.push(`${year}-${month}-${day}`);
  targetDateTitles.push(`${year}${month}${day}`);
}

// 擴大時間範圍以捕獲跨時區的提交（使用第一天和最後一天）
const oldestDate = targetDates[0];
const latestDate = targetDates[targetDates.length - 1];

const oldestYear = oldestDate.getFullYear();
const oldestMonth = String(oldestDate.getMonth() + 1).padStart(2, '0');
const oldestDay = String(oldestDate.getDate()).padStart(2, '0');
const oldestDateStr = `${oldestYear}-${oldestMonth}-${oldestDay}`;

const latestYear = latestDate.getFullYear();
const latestMonth = String(latestDate.getMonth() + 1).padStart(2, '0');
const latestDay = String(latestDate.getDate()).padStart(2, '0');
const latestDateStr = `${latestYear}-${latestMonth}-${latestDay}`;

const oldestTs = Math.floor(new Date(oldestDateStr + 'T00:00:00+08:00').getTime() / 1000) - 86400;
const latestTs = Math.floor(new Date(latestDateStr + 'T23:59:59+08:00').getTime() / 1000) + 86400;

// Slack API 呼叫函數
async function slackApi(endpoint, queryParams = {}) {
  const queryString = Object.entries(queryParams)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  const apiUrl = `https://slack.com/api/${endpoint}${queryString ? '?' + queryString : ''}`;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: apiUrl,
    headers: { 'Authorization': `Bearer ${slackToken}` },
    json: true
  });
  return response;
}

const callSlackApi = slackApi.bind(this);

// 1. 取得頻道成員（支援分頁）
let channelMemberIds = [];
let membersCursor = '';

do {
  const membersParams = { channel: sourceChannel, limit: '200' };
  if (membersCursor) membersParams.cursor = membersCursor;

  const membersResult = await callSlackApi('conversations.members', membersParams);

  if (!membersResult.ok) {
    return [{ json: { error: '無法取得頻道成員', detail: membersResult.error, slackToken, notifyChannel } }];
  }

  channelMemberIds = channelMemberIds.concat(membersResult.members || []);
  membersCursor = membersResult.response_metadata?.next_cursor || '';
} while (membersCursor);

// 2. 取得所有用戶資訊（支援分頁）
const userMap = {};
const botIds = new Set();
let usersCursor = '';

do {
  const usersParams = { limit: '200' };
  if (usersCursor) usersParams.cursor = usersCursor;

  const usersResult = await callSlackApi('users.list', usersParams);

  if (!usersResult.ok) {
    return [{ json: { error: '無法取得用戶列表', detail: usersResult.error, slackToken, notifyChannel } }];
  }

  for (const user of usersResult.members || []) {
    const displayName = user.profile?.display_name || user.real_name || user.name || 'Unknown';
    userMap[user.id] = {
      name: displayName,
      isBot: user.is_bot || false,
      deleted: user.deleted || false
    };
    if (user.is_bot) {
      botIds.add(user.id);
    }
  }

  usersCursor = usersResult.response_metadata?.next_cursor || '';
} while (usersCursor);

// 3. 過濾出真正需要追蹤的成員
const trackableMembers = [];

for (const memberId of channelMemberIds) {
  const userInfo = userMap[memberId];

  if (!userInfo) continue;
  if (userInfo.isBot) continue;
  if (userInfo.deleted) continue;
  if (excludeNames.includes(userInfo.name)) continue;

  trackableMembers.push({ id: memberId, name: userInfo.name });
}

// 4. 取得擴大時間範圍的訊息（支援分頁）
let allMessages = [];
let historyCursor = '';

do {
  const historyParams = {
    channel: sourceChannel,
    oldest: oldestTs.toString(),
    latest: latestTs.toString(),
    limit: '200'
  };
  if (historyCursor) historyParams.cursor = historyCursor;

  const historyResult = await callSlackApi('conversations.history', historyParams);

  if (!historyResult.ok) {
    return [{ json: { error: '無法取得頻道歷史', detail: historyResult.error, slackToken, notifyChannel } }];
  }

  allMessages = allMessages.concat(historyResult.messages || []);
  historyCursor = historyResult.response_metadata?.next_cursor || '';
} while (historyCursor);

// 5. 統計已提交的人員（記錄提交時間和日期）
const submittedMap = new Map(); // userId -> { name, submissions: [{date, time}] }

for (const msg of allMessages) {
  if (!msg.user || !msg.text) continue;

  const text = msg.text;

  // 檢查訊息是否包含任一目標日期
  for (let i = 0; i < targetDateTitles.length; i++) {
    const dateTitle = targetDateTitles[i];
    const dateStr = targetDateStrs[i];

    if (text.includes(dateTitle)) {
      const msgTs = parseFloat(msg.ts);
      const submitTime = new Date(msgTs * 1000);
      // 轉換為台北時間
      const taipeiSubmitTime = new Date(submitTime.getTime() + (taipeiOffset + submitTime.getTimezoneOffset()) * 60 * 1000);

      // 格式化為 YYYY-MM-DD HH:MM:SS
      const sYear = taipeiSubmitTime.getFullYear();
      const sMonth = String(taipeiSubmitTime.getMonth() + 1).padStart(2, '0');
      const sDay = String(taipeiSubmitTime.getDate()).padStart(2, '0');
      const sHours = String(taipeiSubmitTime.getHours()).padStart(2, '0');
      const sMinutes = String(taipeiSubmitTime.getMinutes()).padStart(2, '0');
      const sSeconds = String(taipeiSubmitTime.getSeconds()).padStart(2, '0');
      const timeStr = `${sYear}-${sMonth}-${sDay} ${sHours}:${sMinutes}:${sSeconds}`;

      if (!submittedMap.has(msg.user)) {
        submittedMap.set(msg.user, {
          name: userMap[msg.user]?.name || 'Unknown',
          submissions: []
        });
      }

      const userSubmissions = submittedMap.get(msg.user);
      // 避免重複記錄同一個日期
      if (!userSubmissions.submissions.some(s => s.date === dateStr)) {
        userSubmissions.submissions.push({ date: dateStr, time: timeStr });
      }
    }
  }
}

// 6. 計算已提交和未提交的人員
const submittedList = []; // { name, submissions: [{date, time}] }
const notSubmittedList = [];

for (const member of trackableMembers) {
  if (submittedMap.has(member.id)) {
    const info = submittedMap.get(member.id);
    // 按提交時間排序
    info.submissions.sort((a, b) => a.time.localeCompare(b.time));
    submittedList.push({ name: member.name, submissions: info.submissions });
  } else {
    notSubmittedList.push(member.name);
  }
}

// 按第一次提交時間排序已提交名單
submittedList.sort((a, b) => a.submissions[0].time.localeCompare(b.submissions[0].time));

// 準備輸出
return [{
  json: {
    slackToken,
    notifyChannel,
    checkDates: targetDateStrs,
    trackableCount: trackableMembers.length,
    submittedCount: submittedList.length,
    notSubmittedCount: notSubmittedList.length,
    submittedList: submittedList,
    notSubmittedList: notSubmittedList.sort()
  }
}];

// 從前一節點取得所有資料
const data = $input.first().json;

const slackToken = data.slackToken;
const notifyChannel = data.notifyChannel;

// 檢查是否有錯誤
if (data.error) {
  const errorMsg = `❌ 每日彙報檢查失敗\n錯誤: ${data.error}\n詳情: ${data.detail || '無'}`;

  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://slack.com/api/chat.postMessage',
    headers: {
      'Authorization': `Bearer ${slackToken}`,
      'Content-Type': 'application/json'
    },
    body: {
      channel: notifyChannel,
      text: errorMsg
    },
    json: true
  });

  return [{ json: { sent: true, error: true } }];
}

// 組裝訊息
const checkDatesCount = data.checkDates.length;
let message = `📊 *每日彙報檢查報告*\n`;
message += `📅 檢查日期: ${data.checkDates.join(', ')}\n\n`;
message += `👥 需追蹤人數: ${data.trackableCount}\n`;
message += `✅ 已提交: ${data.submittedCount} 人\n`;
message += `❌ 未提交: ${data.notSubmittedCount} 人\n\n`;

// 顯示已提交名單（智能格式）
if (data.submittedCount > 0) {
  message += `*已提交名單:*\n`;
  for (const item of data.submittedList) {
    if (item.submissions.length === 1) {
      // 只提交 1 次：顯示完整時間
      const fullDateTime = item.submissions[0].time;
      message += `• ${item.name} (submitted at ${fullDateTime})\n`;
    } else if (item.submissions.length > 1) {
      // 提交多次：單行顯示所有時間
      const times = item.submissions.map(s => s.time).join(', ');
      message += `• ${item.name} (submitted at ${times})\n`;
    }
  }
  message += `\n`;
}

// 顯示未提交名單
if (data.notSubmittedCount > 0) {
  message += `*未提交名單:*\n`;
  for (const name of data.notSubmittedList) {
    message += `• ${name}\n`;
  }
} else {
  message += `🎉 太棒了！所有人都已提交每日彙報！`;
}

// 發送訊息
const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/chat.postMessage',
  headers: {
    'Authorization': `Bearer ${slackToken}`,
    'Content-Type': 'application/json'
  },
  body: {
    channel: notifyChannel,
    text: message
  },
  json: true
});

return [{ json: { sent: result.ok, messageTs: result.ts } }];
